//! Public-setter authored originals, never generated by the tested kernel.
#![cfg(feature = "corpus")]
use photocraft_algo::gimp::color_balance::ColorBalance;
use serde_json::Value;

fn samples(bytes: &[u8], precision: &str) -> Vec<f64> {
    if precision.contains("U8") {
        bytes.iter().map(|v| f64::from(*v) / 255.).collect()
    } else if precision.contains("U32") {
        bytes.as_chunks::<4>().0.iter().map(|v| f64::from(u32::from_le_bytes(*v)) / f64::from(u32::MAX)).collect()
    } else if precision.contains("HALF") {
        bytes.as_chunks::<2>().0.iter().map(|v| f64::from(f32::from_bits(photocraft_color::widen_f16_to_f32_bits(u16::from_le_bytes(*v))))).collect()
    } else if precision.contains("U16") {
        bytes.as_chunks::<2>().0.iter().map(|v| f64::from(u16::from_le_bytes(*v)) / 65535.).collect()
    } else if precision.contains("FLOAT") {
        bytes.as_chunks::<4>().0.iter().map(|v| f64::from(f32::from_le_bytes(*v))).collect()
    } else {
        bytes.as_chunks::<8>().0.iter().map(|v| f64::from_le_bytes(*v)).collect()
    }
}
fn encode(v: f64) -> f64 {
    if v <= 0.0031308 { v * 12.92 } else { 1.055 * v.powf(1. / 2.4) - 0.055 }
}
fn decode(v: f64) -> f64 {
    if v <= 0.04045 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) }
}
#[test]
#[ignore = "requires independently authored local Color Balance evidence"]
fn all_tonal_ranges_luminosity_disabled_and_native_alpha_match_originals() {
    verify_packet("color-balance-evidence", 24);
}
#[test]
#[ignore = "requires independently authored local integer half perceptual Color Balance evidence"]
fn integer_half_perceptual_tonal_and_native_alpha_match_originals() {
    verify_packet("color-balance-depth-evidence", 48);
}
fn verify_packet(directory: &str, expected_count: usize) {
    let root = std::path::PathBuf::from(std::env::var_os("PHOTOCRAFT_XCF_FULL_CORPUS").expect("local corpus path")).join(directory);
    let proof: Value = serde_json::from_slice(&std::fs::read(root.join("observations.json")).unwrap()).unwrap();
    let mut count = 0;
    let mut worst = 0.0_f64;
    for row in proof["records"].as_array().unwrap() {
        let precision = row["precision"].as_str().unwrap();
        let linear = precision.ends_with("_LINEAR") && !precision.ends_with("_NON_LINEAR");
        let mut ranges = [[0.; 3]; 3];
        for (range, name) in ranges.iter_mut().zip(["shadows", "midtones", "highlights"]) {
            for (value, axis) in range.iter_mut().zip(["cyan-red", "magenta-green", "yellow-blue"]) {
                *value = row["requested"]["ranges"][name][axis].as_f64().unwrap();
            }
        }
        let config = ColorBalance { ranges, preserve_luminosity: row["requested"]["preserve-luminosity"].as_bool().unwrap() };
        let input = samples(&std::fs::read(root.join(row["reopened"]["layers"][0]["native"]["file"].as_str().unwrap())).unwrap(), precision);
        let reference = samples(&std::fs::read(root.join(row["baked"]["layers"][0]["native"]["file"].as_str().unwrap())).unwrap(), precision);
        assert_eq!(input.len(), 192);
        assert_eq!(reference.len(), 192);
        for (input, reference) in input.as_chunks::<4>().0.iter().zip(reference.as_chunks::<4>().0.iter()) {
            let mut pixel: [f64; 4] = *input;
            let mut output = pixel;
            if row["requested"]["enabled"].as_bool().unwrap() {
                if linear {
                    for value in &mut pixel[..3] {
                        *value = encode(*value);
                    }
                }
                config.try_eval_pixel(&pixel, &mut output).unwrap();
                if linear {
                    for value in &mut output[..3] {
                        *value = decode(*value);
                    }
                }
            }
            assert_eq!(output[3].to_bits(), input[3].to_bits(), "{} alpha", row["id"]);
            assert_eq!(reference[3].to_bits(), input[3].to_bits(), "{} original native alpha", row["id"]);
            for (actual, expected) in output[..3].iter().zip(&reference[..3]) {
                let delta = (actual - expected).abs();
                worst = worst.max(delta);
                let tolerance = if precision.contains("U8") || precision.contains("HALF") { 2. / 255. } else { 1. / 65535. };
                assert!(delta <= tolerance, "{} native {actual} != {expected}, delta {delta}", row["id"]);
            }
        }
        count += 1;
    }
    assert_eq!(count, expected_count);
    println!("Color Balance {count} native original states, worst delta {}/255", worst * 255.);
}
